/**
 * Night City — Discord Theme
 * Recreates the supplied screenshot: monochrome rainy city,
 * translucent glass panels, soft blur, white UI, dark monochrome accents.
 *
 * Compatible style: BetterDiscord / Vencord custom CSS.
 * The supplied screenshot is embedded directly in this CSS, so no
 * separate image file is required.
 */

:root {
  --nc-bg-image: url("data:image/png;base64,");
  --nc-glass: rgba(10, 12, 14, 0.54);
  --nc-glass-strong: rgba(8, 10, 12, 0.72);
  --nc-glass-soft: rgba(255, 255, 255, 0.055);
  --nc-border: rgba(255, 255, 255, 0.18);
  --nc-border-soft: rgba(255, 255, 255, 0.09);
  --nc-text: rgba(245, 245, 245, 0.94);
  --nc-muted: rgba(225, 225, 225, 0.62);
  --nc-dim: rgba(210, 210, 210, 0.42);
  --nc-radius: 16px;
  --nc-blur: 22px;
}

/* =========================
   GLOBAL BACKGROUND
   ========================= */

html,
body,
#app-mount {
  background: #090b0d !important;
}

body {
  background:
    linear-gradient(rgba(4, 5, 6, 0.14), rgba(4, 5, 6, 0.14)),
    var(--nc-bg-image) center center / cover fixed no-repeat !important;
  color: var(--nc-text) !important;
}

#app-mount::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: -1;
  background: rgba(0, 0, 0, 0.12);
}

/* Remove Discord's solid app/background layers */
[class*="appMount"],
[class*="app-"],
[class*="bg-"],
[class*="bg__"],
[class*="layers-"],
[class*="layer-"] {
  background: transparent !important;
}

/* =========================
   GLASS PANELS
   ========================= */

[class*="sidebar-"],
[class*="sidebar__"],
[class*="container-"][class*="themed-"],
[class*="chat-"],
[class*="chatContent-"],
[class*="members-"],
[class*="membersWrap-"],
[class*="content-"],
[class*="contentRegion-"],
[class*="contentRegionScroller-"],
[class*="panels-"],
[class*="nowPlayingColumn-"],
[class*="notice-"],
[class*="header-"][class*="themed-"] {
  background: var(--nc-glass) !important;
  backdrop-filter: blur(var(--nc-blur)) saturate(0.75);
  -webkit-backdrop-filter: blur(var(--nc-blur)) saturate(0.75);
  border-color: var(--nc-border-soft) !important;
}

/* Server rail */
[class*="guilds-"],
[class*="guilds__"] {
  background: rgba(4, 6, 7, 0.62) !important;
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-right: 1px solid var(--nc-border-soft);
}

/* Channel rail */
[class*="sidebar-"] {
  border-right: 1px solid var(--nc-border-soft);
}

/* Main chat */
[class*="chat-"] {
  background: rgba(5, 7, 8, 0.32) !important;
}

/* Member list */
[class*="membersWrap-"] {
  background: rgba(8, 10, 12, 0.46) !important;
  border-left: 1px solid var(--nc-border-soft);
}

/* =========================
   TOP / CHANNEL HEADERS
   ========================= */

[class*="title-"],
[class*="title__"],
[class*="header-"] {
  color: var(--nc-text) !important;
  background: rgba(8, 10, 12, 0.42) !important;
  border-bottom: 1px solid var(--nc-border-soft) !important;
  box-shadow: 0 8px 30px rgba(0,0,0,.12);
}

[class*="topic-"] {
  color: var(--nc-muted) !important;
}

/* =========================
   CHANNEL LIST
   ========================= */

[class*="wrapper-"][class*="modeSelected-"],
[class*="wrapper-"][class*="modeSelected__"],
[class*="containerDefault-"][class*="selected-"] {
  background: rgba(255, 255, 255, 0.13) !important;
  border-radius: 10px !important;
}

[class*="wrapper-"][class*="modeSelected-"] *,
[class*="wrapper-"][class*="modeSelected__"] *,
[class*="containerDefault-"][class*="selected-"] * {
  color: #fff !important;
}

[class*="wrapper-"]:hover,
[class*="containerDefault-"]:hover {
  background: rgba(255,255,255,.075) !important;
  border-radius: 10px;
}

[class*="name-"],
[class*="channelName-"],
[class*="overflow-"] {
  color: rgba(235,235,235,.78) !important;
}

/* =========================
   MESSAGES
   ========================= */

[class*="message-"] {
  background: transparent !important;
}

[class*="message-"]:hover {
  background: rgba(255,255,255,.035) !important;
}

[class*="username-"] {
  color: #f0f0f0 !important;
}

[class*="timestamp-"] {
  color: rgba(220,220,220,.42) !important;
}

[class*="markup-"] {
  color: rgba(245,245,245,.90) !important;
}

[class*="repliedText-"],
[class*="repliedTextContent-"] {
  color: rgba(220,220,220,.62) !important;
}

/* =========================
   MESSAGE COMPOSER
   ========================= */

[class*="channelTextArea-"],
[class*="channelTextArea__"] {
  background: rgba(12,14,16,.62) !important;
  border: 1px solid var(--nc-border) !important;
  border-radius: 15px !important;
  box-shadow: 0 8px 30px rgba(0,0,0,.18);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}

[class*="scrollableContainer-"] {
  background: transparent !important;
}

[class*="placeholder-"] {
  color: rgba(220,220,220,.52) !important;
}

/* =========================
   SEARCH
   ========================= */

[class*="searchBar-"],
[class*="searchBar-"] > div {
  background: rgba(8,10,12,.58) !important;
  border: 1px solid var(--nc-border-soft) !important;
  border-radius: 12px !important;
  color: var(--nc-muted) !important;
}

[class*="search-"] input {
  color: #fff !important;
}

/* =========================
   RIGHT-CLICK / POPOVERS / MENUS
   ========================= */

[class*="menu-"],
[class*="menu__"],
[class*="popout-"],
[class*="popout__"],
[class*="layerContainer-"] > div {
  background: rgba(12,14,16,.86) !important;
  border: 1px solid var(--nc-border) !important;
  border-radius: 14px !important;
  box-shadow: 0 18px 60px rgba(0,0,0,.55) !important;
  backdrop-filter: blur(24px);
  -webkit-backdrop-filter: blur(24px);
}

[class*="item-"][class*="focused-"],
[class*="item-"]:hover {
  background: rgba(255,255,255,.10) !important;
}

/* =========================
   SETTINGS / MODALS
   ========================= */

[class*="modal-"],
[class*="modalRoot-"],
[class*="root-"][class*="fullscreenOnMobile-"],
[class*="standardSidebarView-"] {
  background: rgba(8,10,12,.82) !important;
  backdrop-filter: blur(25px);
  -webkit-backdrop-filter: blur(25px);
}

[class*="contentRegion-"],
[class*="sidebarRegion-"] {
  background: rgba(8,10,12,.46) !important;
}

[class*="card-"] {
  background: rgba(255,255,255,.045) !important;
  border: 1px solid var(--nc-border-soft) !important;
  border-radius: 13px !important;
}

/* =========================
   BUTTONS / ICONS
   ========================= */

button {
  color: rgba(240,240,240,.88) !important;
}

button:hover {
  background: rgba(255,255,255,.08) !important;
}

svg {
  color: rgba(235,235,235,.80);
}

[class*="icon-"] {
  color: rgba(230,230,230,.72) !important;
}

/* =========================
   VOICE / USER PANEL
   ========================= */

[class*="panels-"] {
  background: rgba(7,9,10,.60) !important;
  border-top: 1px solid var(--nc-border-soft);
}

[class*="avatar-"] {
  box-shadow: 0 0 0 1px rgba(255,255,255,.14);
}

/* =========================
   SCROLLBARS
   ========================= */

::-webkit-scrollbar {
  width: 7px;
  height: 7px;
}

::-webkit-scrollbar-track {
  background: transparent !important;
}

::-webkit-scrollbar-thumb {
  background: rgba(255,255,255,.18) !important;
  border-radius: 10px;
}

::-webkit-scrollbar-thumb:hover {
  background: rgba(255,255,255,.28) !important;
}

/* =========================
   TOASTS / NOTICES
   ========================= */

[class*="notice-"] {
  background: rgba(12,14,16,.74) !important;
  border: 1px solid var(--nc-border) !important;
  color: #eee !important;
}

/* Keep Discord's text/icons monochrome */
[class*="lookFilled-"],
[class*="lookOutlined-"] {
  filter: grayscale(1);
}

/* Disable obvious solid white/colored Discord surfaces */
[class*="container-"][class*="themed-"],
[class*="contentRegionScroller-"],
[class*="scroller-"] {
  scrollbar-color: rgba(255,255,255,.18) transparent !important;
}

/* Optional subtle film grain / vignette matching the screenshot */
#app-mount::after {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 9999;
  background:
    radial-gradient(circle at center, transparent 48%, rgba(0,0,0,.20) 100%),
    linear-gradient(rgba(255,255,255,.012) 50%, transparent 50%);
  background-size: 100% 100%, 100% 3px;
  mix-blend-mode: screen;
  opacity: .20;
}
